parameters.jsCode:
// Extrai o texto da mensagem, remetente e tipo (suporta Evolution API, WAHA ou Cloud API)
const body = $input.first().json.body || $input.first().json;
let messageText = '';
let senderPhone = '';

if (body.data && body.data.message) {
  messageText = body.data.message.conversation || body.data.message.extendedTextMessage?.text || '';
  senderPhone = body.data.key?.remoteJid?.replace('@s.whatsapp.net', '') || '';
} else if (body.message) {
  messageText = typeof body.message === 'string' ? body.message : body.message.text || '';
  senderPhone = body.from || body.phone || '';
} else {
  messageText = body.text || body.content || JSON.stringify(body);
  senderPhone = body.sender || 'unknown';
}

return [{
  json: {
    rawMessage: messageText,
    sender: senderPhone,
    timestamp: new Date().toISOString()
  }
}];

